function hasTvEpisodeProgressSnapshot(rows: TVEpisodeRow[]): boolean {
  return rows.some((row) => {
    const watched = String(row.Watched ?? "").trim();
    const watchedAt = String(row.WatchedAt ?? "").trim();
    return watched !== "" || watchedAt !== "";
  });
}

