const DEFAULT_SHELF_SPACING: ShelfSpacing = { horizontal: 14, vertical: 0 };
const normalizeShelfThemeMode = (value: unknown): ShelfThemeMode =>
  value === "dark" || value === "classic" || value === "wood" ? value : "light";
